from pathlib import Path
src=Path('/mnt/data/Darzaan_Clean_Green_Website.html').read_text()
start=src.index("const dataKey='darzaan_clean_demo_bookings'")
end=src.index('</script></body></html>',start)
js=r'''
const appointment={step:1,service:'Designer Blouse',mode:'In-studio consultation',date:'',time:'',name:'',phone:'',email:'',notes:'',consent:false};let reference='';
const services=['Designer Blouse','Bridal & Occasionwear','Saree Styling','Alterations & Fit','Custom Tailoring','Something Else'];
const modes=['In-studio consultation','Video consultation'];
let slotOptions=[];
function escapeText(s){return String(s||'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function show(id){$('#'+id).classList.add('show');document.body.classList.add('lock')}
function hide(id){$('#'+id).classList.remove('show');document.body.classList.remove('lock')}
$$('[data-close]').forEach(e=>e.onclick=()=>hide(e.dataset.close));
$$('.modal-back').forEach(e=>e.addEventListener('click',ev=>{if(ev.target===e)hide(e.id)}));
document.addEventListener('keydown',e=>{if(e.key==='Escape')$$('.modal-back.show').forEach(m=>hide(m.id))});
async function sendJSON(path,body){
 const response=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});
 const data=await response.json().catch(()=>({detail:'Service temporarily unavailable'}));
 if(!response.ok)throw new Error(typeof data.detail==='string'?data.detail:'Please check your details and try again.');
 return data;
}
function getDates(){const now=new Date();const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(now);const p=Object.fromEntries(parts.map(x=>[x.type,x.value]));const utc=new Date(Date.UTC(+p.year,+p.month-1,+p.day));const results=[];for(let i=1;i<15;i++){const d=new Date(utc.getTime()+i*864e5);if(d.getUTCDay()!==0)results.push({id:d.toISOString().slice(0,10),text:d.toLocaleDateString('en-IN',{timeZone:'UTC',weekday:'short',day:'numeric',month:'short',year:'numeric'})})}return results}
function openBooking(service){appointment.step=1;if(service&&services.includes(service))appointment.service=service;reference='';appointment.time='';renderBooking();show('bookingModal')}
$$('[data-book]').forEach(b=>b.onclick=()=>openBooking(b.dataset.book||null));
async function refreshSlots(){const el=$('#slotStatus');if(el)el.textContent='Checking live availability…';try{const r=await fetch('/api/slots?date='+encodeURIComponent(appointment.date)+'&mode='+encodeURIComponent(appointment.mode));if(!r.ok)throw new Error('Unavailable');const body=await r.json();slotOptions=body.slots;if(!slotOptions.some(s=>s.time===appointment.time&&s.available))appointment.time='';if(appointment.step===2)renderBooking();}catch{slotOptions=[];if(appointment.step===2){let b=$('#slotStatus');if(b)b.textContent='Could not load available times. Please try again.'}}}
function renderBooking(){for(let i=1;i<=3;i++)$('#pr'+i).classList.toggle('on',appointment.step===i);const target=$('#stage');
if(reference){target.innerHTML=`<div class="success"><div class="eyebrow">Appointment request received</div><h3>Thank you, ${escapeText(appointment.name)}.</h3><p>Your request reference is <strong>${escapeText(reference)}</strong>. This is a request, not a confirmed booking. The Darzaan team will confirm your slot.</p><p><strong>${escapeText(appointment.date)} · ${escapeText(appointment.time)}</strong><br>${escapeText(appointment.service)}</p><button class="btn light" id="again">Book another appointment</button></div>`;$('#again').onclick=()=>{reference='';appointment.step=1;appointment.time='';renderBooking()};return;}
if(appointment.step===1){target.innerHTML=`<h3>What brings you to Darzaan?</h3><p>Every beautiful outfit begins with a conversation.</p><div class="choices">${services.map(s=>`<button type="button" class="choice ${appointment.service===s?'on':''}" data-service="${s}">${s}</button>`).join('')}</div><div class="field" style="margin-top:22px"><label for="modeSelect">How would you like to meet?</label><select id="modeSelect">${modes.map(m=>`<option>${m}</option>`).join('')}</select></div><div class="modal-actions"><span></span><button class="btn" id="nextBook">Choose a time →</button></div>`;$('#modeSelect').value=appointment.mode;$('#modeSelect').onchange=e=>{appointment.mode=e.target.value;appointment.time=''};$$('[data-service]',target).forEach(b=>b.onclick=()=>{appointment.service=b.dataset.service;renderBooking()});$('#nextBook').onclick=()=>{appointment.step=2;appointment.time='';slotOptions=[];renderBooking();refreshSlots()};}
else if(appointment.step===2){const ds=getDates();if(!ds.find(d=>d.id===appointment.date))appointment.date=ds[0]?.id||'';target.innerHTML=`<h3>A time for you.</h3><p>Select an available consultation time. Your request will be reviewed by our team.</p><div class="field"><label for="dateSelect">Preferred date</label><select id="dateSelect">${ds.map(d=>`<option value="${d.id}">${d.text}</option>`).join('')}</select></div><div class="times">${slotOptions.map(s=>`<button type="button" ${s.available?'':'disabled'} class="choice ${appointment.time===s.time?'on':''}" data-time="${s.time}">${s.time}${s.available?'':' · Taken'}</button>`).join('')}</div><p id="slotStatus" role="status" style="font-size:12px">${slotOptions.length?'Available times are shown above.':'Checking live availability…'}</p><div class="modal-actions"><button class="btn light" id="backBook">← Back</button><button class="btn" id="nextBook" ${appointment.time?'':'disabled'}>Your details →</button></div>`;$('#dateSelect').value=appointment.date;$('#dateSelect').onchange=e=>{appointment.date=e.target.value;appointment.time='';slotOptions=[];renderBooking();refreshSlots()};$$('[data-time]',target).forEach(b=>b.onclick=()=>{appointment.time=b.dataset.time;renderBooking()});$('#backBook').onclick=()=>{appointment.step=1;renderBooking()};$('#nextBook').onclick=()=>{if(!appointment.time)return;appointment.step=3;renderBooking()};}
else{target.innerHTML=`<h3>And whom shall we welcome?</h3><p>Your details help our designers prepare for your visit.</p><form id="appointmentForm" class="fields"><div class="field"><label for="apName">Full name *</label><input id="apName" autocomplete="name" maxlength="80" required value="${escapeText(appointment.name)}" placeholder="Your full name"></div><div class="field"><label for="apPhone">WhatsApp mobile number *</label><input id="apPhone" type="tel" inputmode="numeric" autocomplete="tel" required pattern="[6-9][0-9]{9}" value="${escapeText(appointment.phone)}" placeholder="10-digit Indian number"></div><div class="field full"><label for="apEmail">Email (optional)</label><input id="apEmail" type="email" maxlength="180" value="${escapeText(appointment.email)}" placeholder="you@example.com"></div><div class="field full"><label for="apNotes">Anything you'd like us to know?</label><textarea id="apNotes" maxlength="700" rows="3" placeholder="Your occasion, inspiration or questions">${escapeText(appointment.notes)}</textarea></div><label class="check field full"><input id="apConsent" type="checkbox" required><span>I agree that Darzaan may store these details and contact me about my appointment via phone or WhatsApp. Read our <a href="#privacy" target="_blank">privacy notice</a>.</span></label><div class="field full" style="display:none"><label>Leave blank<input id="apWebsite" autocomplete="off" tabindex="-1"></label></div><div class="field full"><p id="bookingError" role="alert" style="color:#9b263a"></p><div class="modal-actions" style="margin-top:0"><button type="button" class="btn light" id="backBook">← Back</button><button type="submit" class="btn" id="bookingSubmit">Send appointment request →</button></div></div></form>`;$('#apConsent').checked=appointment.consent;$('#backBook').onclick=()=>{appointment.step=2;renderBooking()};$('#appointmentForm').onsubmit=async e=>{e.preventDefault();appointment.name=$('#apName').value.trim();appointment.phone=$('#apPhone').value.trim();appointment.email=$('#apEmail').value.trim();appointment.notes=$('#apNotes').value.trim();appointment.consent=$('#apConsent').checked;if(!/^[6-9][0-9]{9}$/.test(appointment.phone)||!appointment.name||!appointment.consent){$('#bookingError').textContent='Please enter your name, a valid Indian mobile number and consent.';return}const btn=$('#bookingSubmit');btn.disabled=true;btn.textContent='Submitting…';try{let result=await sendJSON('/api/appointments',{...appointment,website:$('#apWebsite').value});reference=result.reference;renderBooking();}catch(err){$('#bookingError').textContent=err.message;btn.disabled=false;btn.textContent='Send appointment request →'} };}}
$('#franchiseForm').onsubmit=async e=>{e.preventDefault();const lead={name:$('#fname').value.trim(),phone:$('#fphone').value.trim(),type:$('#ftype').value,area:$('#farea').value.trim(),consent:$('#fconsent').checked,website:''};const status=$('#fmessage');status.textContent='Submitting…';try{let response=await sendJSON('/api/franchise',lead);status.textContent=response.message;e.target.reset();}catch(err){status.textContent=err.message}};
'''
html=src[:start]+js+src[end:]
# Eliminate publicly exposed demo desk (including its markup).
from re import sub
html=sub(r'<button class="desk" id="openDesk">.*?</button>','',html,flags=0)
html=sub(r'<div class="modal-back" id="deskModal".*?</div></div>', '', html,flags=0)
html=html.replace('Website concept prototype — not a live booking or payment service.','Appointments are requests until confirmed by our team.')
html=html.replace('This is a local prototype and information is not transmitted to Darzaan.','Darzaan may store and use my information to contact me about franchise opportunities.')
# Intro text to original booking: skip prototype wording; all other original retained.
html=html.replace('These are demo slot preferences, not live availability.','Times shown reflect current request availability.')
# privacy route provision
html=html.replace("const pages=['home','collections','services','studio','appointments','franchise'];","const pages=['home','collections','services','studio','appointments','franchise','privacy'];")
privacy='''<section class="page" data-page="privacy"><div class="wrap" style="max-width:850px;padding:80px 24px"><div class="eyebrow">Darzaan | Information practices</div><h1>Privacy notice</h1><p>We collect your name, mobile number, service preferences, requested appointment date and time, and any optional details you provide. We use this information to respond to your appointment or franchise enquiry and provide requested customer service. We may use an authorized messaging provider to send appointment-related WhatsApp notifications if configured.</p><p>We do not collect online payments through this site. We restrict employee access to enquiry records, and we do not sell customer information to advertisers.</p><p>To request access, correction or deletion, contact Darzaan using the contact details supplied by the team. The operator must publish verified legal entity details, a designated privacy contact, retention periods and required statutory disclosures before public launch.</p><p><a href="#home" class="btn light">Back to Darzaan</a></p></div></section>'''
html=html.replace('</main>',privacy+'</main>')
html=html.replace('© 2026 Darzaan. All rights reserved.', '© 2026 Darzaan. All rights reserved. &nbsp; <a href="#privacy">Privacy notice</a>.')
Path('/mnt/data/darzaan_live/static/index.html').write_text(html)
print(len(html), 'desk', 'id="deskModal"' in html)
